`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------------
// TW-HBM-PGLG 2026-10-19: soft glue children of the REGION form of the LIGHT SU port-group slice. The wires-only flat
// parent ot_hbm_su_static_pgslice_rgf (generated by tools/hbm_static/su_pgslice_rgf_gen.py) instantiates them next to the
// 32 KIND0 lane leaves and 32 CLOSED bank6_clock banks; tools/landed_parent/lp.py lands every region crossing
// (ot_hbm_su_static_pgslice_rgf_lp = the kit top of hbm_su_pgslice_lg_light_d4g). Regions (stacked R0 | R1 | S | R2 | R3):
//   s  : u_sin (fill destination delay, RF local copy, per-region store-command bundles, S checks) + u_sout (drain select,
//        reducer operand stage, pre-tree operands, inject data, sticky fault)
//   r<r>: u_rg<r> (control replicas, lane operand / RF mux, bank port drive, region checks) + lanes / banks 8r..8r+7;
//        inner regions r1 / r2 also hold the relays of the outer region (u_rly<r>: inbound, u_rlyb<r>: return) and the
//        2-stage return delay u_dly<r> that aligns their own return with the outer one.
// Flat-parent timing against ot_hbm_su_static_pgslice_lg (the lp landings add E+1 per crossing on top, see the record):
//   inner regions r1/r2 = pgslice timing; outer r0/r3 one edge later (relay); every return reaches u_sout 2 edges later
//   (dly / relay+frame), so u_sout's drain line is 3+2 long, its red_sel / tree_cmd / rf_dsec are issued +2, the S
//   check bundle is pipelined 3 (= the region checks' rflt + 2), the VM write gets WQ_PAD alignment stages.
// Behaviour unchanged otherwise (same checks, same MUT 1/2/4/10/11 hooks).
// ---------------------------------------------------------------------------------------------------------------------

// plain register delay (relay / alignment): W bits, N stages, no reset (bubbles ride like data)
module ot_hbm_su_pgrg_dly #(parameter integer W=1, N=1)(input wire ck, input wire [W-1:0] d, output wire [W-1:0] q);
 reg [W-1:0] r [0:N-1]; integer j;
 always @(posedge ck) begin r[0]<=d; for(j=1;j<N;j=j+1) r[j]<=r[j-1]; end
 assign q=r[N-1];
endmodule

// HBM-PGLG2 2026-10-19: FACE relay (S region, clock ck_s): one plain register stage between a die face (W command side /
// E stream side) and the S-band service u_sin / u_sout / the S landings. The kit --cts gate (f5d151f2e) found 113 stages
// whose fixed terminals sat on BOTH faces (W pin -> S register -> E pin, 1235.52 um outline): u_sin.cp (pos/vmw + ij_v),
// u_sout.slice_x (red_sel -> slice_x) and the di landing slots (vmw_cmd + ij_v/ij_row). Every S-bound input now crosses
// one face relay, so no S register sees pins of both faces and each face->relay->S->face hop is ~1/3 of the width
// (<= ~410 um). Uniform +1 on EVERY S-bound input (both faces): the core is the previous core delayed one edge, so all
// internal alignments hold; u_sout WQ_PAD 2 -> 1 keeps the VM write (su_wq) offset unchanged. BYP 1 = relay bypassed
// (glue mutant GMUT 23 on the E relay: must FAIL lockstep).
module ot_hbm_su_pgrg_frly #(parameter integer W=1, BYP=0)(input wire ck, input wire [W-1:0] d, output wire [W-1:0] q);
 reg [W-1:0] r;
 always @(posedge ck) r<=d;
 assign q=(BYP!=0)?d:r;
endmodule

// ------------------------------------------------------------------------------------------------ S: inbound service
// di<r> = {fw, row9, data256, rv5, row9, dwn, row9, words256} = the store-command bundle of store group r (h r%2, hi r/2)
module ot_hbm_su_pgrg_sin #(
 parameter integer QID=1,G=2,READ_RETURN=10,MULTIRATE=1,COLLPORT=1,RF_LOCAL=1,STRAP=1,MUT=0
)(
 input wire ck, input wire rst_n,
 input wire [3:0] pos,
 input wire [2*30-1:0] vmr_cmd,
 input wire [2*39-1:0] vmw_cmd,
 input wire [2*257-1:0] su_rr,
 input wire [3:0] ij_v, input wire [35:0] ij_row, input wire ij_bad,
 input wire pg_fault,
 input wire [4*32-1:0] rf_bword,
 input wire [4*9-1:0] rf_bcmd,
 input wire [1:0] dw_v,
 input wire [17:0] dw_row,
 input wire [1023:0] dw_d,
 output wire [163:0] rf_u,                  // {rf_bword 128, rf_bcmd 36} as the lanes consume them
 output wire [541:0] di0, di1, di2, di3,
 output wire s_cond                         // S checks, pipelined 3 (flat alignment with the region checks)
);
 wire [1:0] q_id=(STRAP!=0)?pos[3:2]:2'(QID);
 wire [1:0] g_id=(STRAP!=0&&MUT!=11)?pos[1:0]:2'(G);
 wire pos_bad=(STRAP!=0)&&((g_id[1]!=(G>=2))||((q_id==2'd0&&g_id==2'd0)!=(QID==0&&G==0)));
 // ---- FILL destination delay line (as pgslice)
 localparam integer RR=MULTIRATE ? 12 : READ_RETURN;
 localparam integer FD=(MUT==1)?RR-1:RR;
 reg [10:0] fd [0:1][0:RR];
 reg [1:0] fr_v; reg [1:0] fr_hi; reg [8:0] fr_row [0:1]; reg [255:0] fr_dat [0:1];
 wire [1:0] cmd_far, rf_drain_bad;
 for(genvar h=0;h<2;h=h+1)begin:g_fill
  wire [29:0] c=vmr_cmd[h*30+:30];
  wire [38:0] w=vmw_cmd[h*39+:39];
  assign cmd_far[h]=(c[29]&&c[11:9]!={g_id,1'(h)})||(w[38]&&!w[37]&&w[35:33]!={g_id,1'(h)});
  assign rf_drain_bad[h]=w[38]&&w[37]&&!(g_id==2'd0&&h==0);
  integer k;
  always @(posedge ck)
   if(!rst_n)begin for(k=0;k<=RR;k=k+1)fd[h][k]<=11'd0; fr_v[h]<=1'b0; end
   else begin
    fd[h][0]<={c[29],c[12],c[8:0]};for(k=1;k<=RR;k=k+1)fd[h][k]<=fd[h][k-1];
    fr_v[h]<=fd[h][FD][10];
   end
  always @(posedge ck)begin fr_hi[h]<=fd[h][FD][9];fr_row[h]<=fd[h][FD][8:0];fr_dat[h]<=su_rr[h*257+:256];end
 end
 // ---- RF local copy
 wire [4*32-1:0] rf_bword_u; wire [4*9-1:0] rf_bcmd_u;
 if(RF_LOCAL)begin:g_rf_local
  reg [4*32-1:0] rf_bword_l; reg [4*8-1:0] rf_badr_l; reg [3:0] rf_bv_l; integer vb;
  always @(posedge ck)begin
   rf_bword_l<=rf_bword;
   for(vb=0;vb<4;vb=vb+1)rf_badr_l[vb*8+:8]<=rf_bcmd[vb*9+:8];
  end
  always @(posedge ck)
   if(!rst_n)rf_bv_l<=4'd0;
   else for(vb=0;vb<4;vb=vb+1)rf_bv_l[vb]<=rf_bcmd[vb*9+8];
  assign rf_bword_u=rf_bword_l;
  assign rf_bcmd_u={rf_bv_l[3],rf_badr_l[24+:8],rf_bv_l[2],rf_badr_l[16+:8],rf_bv_l[1],rf_badr_l[8+:8],rf_bv_l[0],rf_badr_l[0+:8]};
 end else begin:g_rf_direct
  assign rf_bword_u=rf_bword; assign rf_bcmd_u=rf_bcmd;
 end
 assign rf_u={rf_bword_u,rf_bcmd_u};
 // ---- per store group bundles (drain / inject port-5 read, fill write, delivery write)
 wire [1:0] dr_v,dr_hi; wire [8:0] dr_row [0:1];
 for(genvar h=0;h<2;h=h+1)begin:g_dr
  wire [38:0] w=vmw_cmd[h*39+:39];
  assign dr_v[h]=w[38]&&!w[37]; assign dr_hi[h]=w[36]; assign dr_row[h]=w[32:24];
 end
 wire [541:0] di [0:3]; wire [3:0] st_inj_drain;
 for(genvar r=0;r<4;r=r+1)begin:g_dis
  localparam integer H=r%2, HI=r/2;
  wire fw=fr_v[H]&&fr_hi[H]==1'(HI);
  wire drn=dr_v[H]&&dr_hi[H]==1'(HI);
  wire ijn=ij_v[2*HI+H];
  wire [8:0] ra5=ijn?ij_row[9*(2*HI+H)+:9]:dr_row[H];
  wire dwn=(COLLPORT!=0)&&dw_v[HI];
  wire [255:0] dwd;
  for(genvar j=0;j<8;j=j+1)begin:g_w
   assign dwd[j*32+:32]=dw_d[512*HI+32*((MUT==10)?15-(8*H+j):(8*H+j))+:32];
  end
  assign st_inj_drain[r]=drn&&ijn;
  assign di[r]={fw,fr_row[H],fr_dat[H],drn||ijn,ra5,dwn,dw_row[9*HI+:9],dwd};
 end
 assign di0=di[0]; assign di1=di[1]; assign di2=di[2]; assign di3=di[3];
 // ---- S checks: pipelined 3 (the region checks reach u_sout as rflt + 2 return stages)
 wire c0=pg_fault||(|cmd_far)||(|rf_drain_bad)||(|st_inj_drain)||ij_bad||pos_bad;
 reg [2:0] cp;
 always @(posedge ck) if(!rst_n) cp<=3'd0; else cp<={cp[1:0],c0};
 assign s_cond=cp[2];
endmodule

// ------------------------------------------------------------------------------------------------ region glue (r)
// lane j of region r = slice lane / bank n = 8r + j. ctl<j> = the replica of lane j (decoded at the lane pins by the
// parent). lo = lane outputs packed per lane (LOW 282 b, order below); bq = bank read data (8 x 192).
module ot_hbm_su_pgrg_rg #(
 parameter integer R=0,QID=1,G=2,STRAP=1,MUT=0
)(
 input wire ck, input wire rst_n,
 input wire [3:0] pos,
 input wire [1741:0] control,
 input wire [163:0] rf_u,
 input wire [541:0] di,
 output wire [1741:0] ctl0, ctl1, ctl2, ctl3, ctl4, ctl5, ctl6, ctl7,
 output wire [8*11-1:0] lid,                // lane_id per lane
 output wire [8*128-1:0] rd_q,              // lane operand streams (bank or RF)
 input wire [8*282-1:0] lo,                 // {vi_re, vm_we, kv_we, ro_v, fault, coll, vi_addr24, vm_waddr24, kv_waddr24,
                                            //  rd_addr96, rd_re4, rd_src8, vm_wdata32, kv_wdata32, ro_x32} x 8 (lane 0 low)
 output wire [8*6-1:0] b_rv,                // bank read_v
 output wire [8*54-1:0] b_ra,               // bank read_addr
 output wire [7:0] b_wv,                    // bank write_v
 output wire [8*9-1:0] b_wa,                // bank write_addr
 output wire [8*32-1:0] b_wd,               // bank write_data
 input wire [8*192-1:0] bq,                 // bank read_data
 output wire [520:0] ret                    // {rflt, ro_v8, ro_x 8x32, port-5 q 8x32}
);
 wire [1:0] q_id=(STRAP!=0)?pos[3:2]:2'(QID);
 wire [1:0] g_id=(STRAP!=0&&MUT!=11)?pos[1:0]:2'(G);
 wire [127:0] rfw=rf_u[163:36]; wire [35:0] rfc=rf_u[35:0];
 wire fw_l; wire [8:0] frow_l; wire [255:0] fdat_l; wire rv5_l; wire [8:0] ra5_l; wire dwn_l; wire [8:0] dwr_l; wire [255:0] dwd_l;
 assign {fw_l,frow_l,fdat_l,rv5_l,ra5_l,dwn_l,dwr_l,dwd_l}=di;
 // control replicas (one beside each lane; data stage, no reset: NOP control before the first op)
 reg [1741:0] ctl [0:7];
 for(genvar k=0;k<8;k=k+1)begin:g_replica always @(posedge ck) ctl[k]<=control; end
 assign ctl0=ctl[0]; assign ctl1=ctl[1]; assign ctl2=ctl[2]; assign ctl3=ctl[3];
 assign ctl4=ctl[4]; assign ctl5=ctl[5]; assign ctl6=ctl[6]; assign ctl7=ctl[7];
 wire [7:0] ro_v, l_fault, l_coll, st_conflict, st_id_fault, rf_src_bad;
 wire [255:0] ro_x, q5;
 for(genvar j=0;j<8;j=j+1)begin:g_ln
  localparam integer n=8*R+j;
  assign lid[j*11+:11]=(STRAP!=0)?{4'd0,1'(n>=16),g_id,4'(n%16)}:11'((n<16)?16*G+n:64+16*G+(n-16));
  wire [6:0] st_lid=(STRAP!=0)?{1'(n>=16),g_id,4'(n%16)}:7'((n<16)?16*G+n:64+16*G+(n-16));
  wire vi_re,vm_we,kv_we; wire [23:0] vi_addr,vm_waddr,kv_waddr; wire [95:0] rd_addr; wire [3:0] rd_re; wire [7:0] rd_src;
  wire [31:0] vm_wdata,kv_wdata;
  assign {vi_re,vm_we,kv_we,ro_v[j],l_fault[j],l_coll[j],vi_addr,vm_waddr,kv_waddr,rd_addr,rd_re,rd_src,vm_wdata,kv_wdata,ro_x[j*32+:32]}=lo[j*282+:282];
  wire [191:0] q=bq[j*192+:192];
  wire [53:0] ra; wire [5:0] rv;
  for(genvar p=0;p<4;p=p+1)begin:g_read
   wire [23:0] a=rd_addr[p*24+:24];
   assign ra[p*9+:9]={a[17:16],a[13:7]}; assign rv[p]=rd_re[p]&&rd_src[2*p+:2]==2'd0;
  end
  assign ra[4*9+:9]={vi_addr[16+:2],vi_addr[7+:7]}; assign rv[4]=vi_re;
  assign ra[5*9+:9]=ra5_l; assign rv[5]=rv5_l;
  assign q5[j*32+:32]=q[5*32+:32];
  assign b_rv[j*6+:6]=rv; assign b_ra[j*54+:54]=ra;
  wire lw=vm_we|kv_we;
  wire [23:0] la=vm_we?vm_waddr:kv_waddr;
  wire [31:0] ldat=vm_we?vm_wdata:kv_wdata;
  assign st_conflict[j]=(fw_l&&lw)||(fw_l&&dwn_l)||(dwn_l&&lw);
  assign b_wv[j]=lw|fw_l|dwn_l;
  assign b_wa[j*9+:9]=fw_l?frow_l:dwn_l?dwr_l:{la[17:16],la[13:7]};
  assign b_wd[j*32+:32]=fw_l?fdat_l[j*32+:32]:dwn_l?dwd_l[j*32+:32]:ldat;
  reg idf; integer p2;
  always @*begin
   idf=lw&&(la[6:0]!=st_lid||la[15:14]!=q_id);
   for(p2=0;p2<4;p2=p2+1)if(rv[p2]&&(rd_addr[p2*24+:7]!=st_lid||rd_addr[p2*24+14+:2]!=q_id))idf=1;
  end
  assign st_id_fault[j]=idf;
  // RF broadcast into the lane operands (stream source code 1 rides the read: select held n+2..n+3)
  wire [3:0] is_rf; reg [3:0] src1_a,src1_b,src1_c;
  for(genvar p=0;p<4;p=p+1)begin:g_p
   assign is_rf[p]=rd_re[p]&&rd_src[2*p+:2]==2'd1;
   assign rd_q[(j*4+p)*32+:32]=((MUT==4)?src1_b[p]:src1_c[p])?rfw[p*32+:32]:q[p*32+:32];
  end
  always @(posedge ck)begin src1_a<=is_rf;src1_b<=src1_a;src1_c<=src1_b;end
  reg rsb; integer p3;
  always @*begin
   rsb=0;
   for(p3=0;p3<4;p3=p3+1)begin
    if(rd_re[p3]&&rd_src[2*p3+1])rsb=1;
    if(is_rf[p3]&&(!rfc[p3*9+8]||rd_addr[p3*24+:24]!={16'd0,rfc[p3*9+:8]}))rsb=1;
   end
  end
  assign rf_src_bad[j]=rsb;
 end
 reg rflt;
 always @(posedge ck)
  if(!rst_n)rflt<=1'b0;
  else if((|l_fault)||(|l_coll)||(|st_conflict)||(|st_id_fault)||(|rf_src_bad))rflt<=1'b1;
 assign ret={rflt,ro_v,ro_x,q5};
endmodule

// ------------------------------------------------------------------------------------------------ S: outbound service
// ret<r> arrive 2 edges after the flat slice saw them (flat parent) + the lp landing offset; red_sel / tree_cmd / rf_dsec
// are issued by the compiler with the same total offset.
module ot_hbm_su_pgrg_sout #(
 parameter integer QID=1,G=2,STRAP=1,PRETREE=0,RF_LOCAL=1,MUT=0,
 parameter integer WQ_PAD=2,              // VM-write alignment stages: total drain offset a multiple of 3 (4:3 bridge)
 parameter integer FRLY=0                 // HBM-PGLG2: 1 = W-face relay stage on rf_dsec / red_sel / tree_cmd (u_sout-only
                                          // issue ports; the other S-bound inputs cross ot_hbm_su_pgrg_frly in the parent)
)(
 input wire ck, input wire rst_n,
 input wire [3:0] pos,
 input wire [2*39-1:0] vmw_cmd,
 input wire [255:0] rf_dsec_p,
 input wire [11:0] red_sel_p,
 input wire [11:0] tree_cmd_p,
 input wire [520:0] ret0, ret1, ret2, ret3,
 input wire s_cond,
 output reg [31:0] slice_x,
 output wire [66:0] tree_o,
 output wire [1023:0] pt_ro_x,
 output wire [31:0] pt_ro_v,
 output wire [1023:0] inj_q,
 output wire [2*281-1:0] su_wq,
 output reg fault
);
 wire [1:0] g_id=(STRAP!=0&&MUT!=11)?pos[1:0]:2'(G);
 wire [255:0] rf_dsec; wire [11:0] red_sel, tree_cmd;
 if(FRLY!=0)begin:g_frly
  reg [279:0] fr; always @(posedge ck) fr<={rf_dsec_p,red_sel_p,tree_cmd_p};
  assign {rf_dsec,red_sel,tree_cmd}=fr;
 end else begin:g_nofrly
  assign rf_dsec=rf_dsec_p; assign red_sel=red_sel_p; assign tree_cmd=tree_cmd_p;
 end
 localparam integer DDL=3+2-((MUT==21)?1:0);
 wire [520:0] rt [0:3]; assign rt[0]=ret0; assign rt[1]=ret1; assign rt[2]=ret2; assign rt[3]=ret3;
 wire [3:0] rflt; wire [31:0] ro_v; wire [1023:0] ro_x, q5;
 for(genvar r=0;r<4;r=r+1)begin:g_un
  assign {rflt[r],ro_v[8*r+:8],ro_x[256*r+:256],q5[256*r+:256]}=rt[r];
 end
 assign inj_q=q5; assign pt_ro_x=ro_x; assign pt_ro_v=ro_v;
 wire [255:0] rf_dsec_u;
 if(RF_LOCAL)begin:g_rf_local reg [255:0] l; always @(posedge ck) l<=rf_dsec; assign rf_dsec_u=l; end
 else begin:g_rf_direct assign rf_dsec_u=rf_dsec; end
 // ---- DRAIN: delay line DDL + registered 2:1 group select + WQ_PAD alignment
 reg [26:0] dd [0:1][0:DDL-1];
 for(genvar h=0;h<2;h=h+1)begin:g_drain
  wire [38:0] w=vmw_cmd[h*39+:39];
  integer k;
  always @(posedge ck)
   if(!rst_n)begin for(k=0;k<DDL;k=k+1)dd[h][k]<=27'd0; end
   else begin dd[h][0]<={w[38],w[37],w[36],w[23:0]}; for(k=1;k<DDL;k=k+1)dd[h][k]<=dd[h][k-1]; end
  wire hi=dd[h][DDL-1][24]^((MUT==2)?1'b1:1'b0);
  reg [255:0] sel; integer kk;
  always @*begin
   for(kk=0;kk<8;kk=kk+1)sel[kk*32+:32]=q5[256*(2*hi+h)+kk*32+:32];
   if(dd[h][DDL-1][25])sel=rf_dsec_u;
  end
  reg [WQ_PAD:0] wq_v; reg [279:0] wq_p [0:WQ_PAD]; integer t;
  always @(posedge ck)
   if(!rst_n)wq_v<='0; else begin wq_v[0]<=dd[h][DDL-1][26]; for(t=1;t<=WQ_PAD;t=t+1)wq_v[t]<=wq_v[t-1]; end
  always @(posedge ck)begin wq_p[0]<={dd[h][DDL-1][23:8],sel,dd[h][DDL-1][7:0]}; for(t=1;t<=WQ_PAD;t=t+1)wq_p[t]<=wq_p[t-1]; end
  assign su_wq[h*281+:281]={wq_v[WQ_PAD],wq_p[WQ_PAD]};
 end
 // ---- reducer operand stage
 wire [6:0] rl=red_sel[6:0];
 wire mine=red_sel[11]&&!red_sel[7]&&(rl[5:4]==g_id);
 wire [4:0] rn={rl[6],rl[3:0]};
 wire ext=red_sel[10:8]==3'd0||red_sel[10:8]==3'd1||red_sel[10:8]==3'd3;
 wire red_bad=mine&&ext&&!ro_v[rn];
 always @(posedge ck)slice_x<=ro_x[rn*32+:32];
 // ---- PRETREE (HH-6) on the aligned operands (kit: PRETREE 0, the die sibling su_pt takes pt_ro_x / pt_ro_v)
 wire pt_fault;
 if(PRETREE!=0)begin:g_pretree
  ot_hbm_su_red_pretree_s #(.LAT(6)) u_pt(.clk(ck),.rst_n(rst_n),.tree_cmd(tree_cmd),.ro_x(ro_x),.ro_v(ro_v),
   .tree_o(tree_o),.fault(pt_fault));
 end else begin:g_no_pretree
  assign tree_o=67'd0; assign pt_fault=1'b0;
 end
 // ---- sticky fault
 reg a_q;
 always @(posedge ck) a_q<=red_bad||pt_fault;
 always @(posedge ck)
  if(!rst_n)fault<=1'b0;
  else if(s_cond||a_q||(|rflt))fault<=1'b1;
endmodule
`default_nettype wire
